// LeetCode 0207 - Course Schedule
func canFinish(numCourses int, prerequisites [][]int) bool { graph := make([][]int, numCourses); indegree := make([]int, numCourses); for _, edge := range prerequisites { course, pre := edge[0], edge[1]; graph[pre] = append(graph[pre], course); indegree[course]++ }; queue := make([]int, 0, numCourses); for course := 0; course < numCourses; course++ { if indegree[course] == 0 { queue = append(queue, course) } }; taken := 0; for len(queue) > 0 { course := queue[0]; queue = queue[1:]; taken++; for _, next := range graph[course] { indegree[next]--; if indegree[next] == 0 { queue = append(queue, next) } } }; return taken == numCourses }
